package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveRate {
    public void save(@PathVariable("sheetId") String sheetId, @Val RateInput input,
            ServerHttpConnection connection, RateRepository repository, Audit audit, Rollup rollup, Out<Rate> rate)
            throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        rate.set(set(id, by, input, repository, audit, rollup));
    }

    /** Set a rate on the sheet, writing RATE_SET and the rollups it changes. */
    static Rate set(String id, String by, RateInput input, RateRepository repository, Audit audit, Rollup rollup) {
        Rollup.Snapshot before = rollup.take(id);
        Rate saved = repository.set(id, input.grade(), input.pct(), input.from(), input.to());
        audit.record("RATE_SET sheet=" + id + " by=" + by + " grade=" + saved.grade() + " rate=" + saved.pct()
                + (saved.from() == null ? "" : " from=" + saved.from())
                + (saved.to() == null ? "" : " to=" + saved.to()));
        rollup.record(id, by, before);
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the rate import box: each non-blank line is grade,rate,from,to (the from and to may be absent or
 *  blank), checked by the rate form's rules. An import with no lines, or a line with more fields, is refused. */
public class ValidateRateImport {
    public void validate(@RequestBody RateImportRequest request, Out<RateImportInput> rates) throws BadRequestException {
        String text = request == null || request.text() == null ? "" : request.text();
        List<RateInput> checked = new ArrayList<>();
        int n = 0;
        for (String raw : text.split("\r?\n", -1)) {
            n++;
            if (raw.isBlank()) {
                continue;
            }
            String[] f = raw.split(",", -1);
            try {
                if (f.length > 4) {
                    throw new BadRequestException("a line is grade,rate,from,to");
                }
                checked.add(ValidateRate.check(new RateRequest(f[0], f.length > 1 ? f[1] : "",
                        f.length > 2 ? f[2] : "", f.length > 3 ? f[3] : "")));
            } catch (BadRequestException e) {
                throw new BadRequestException("line " + n + ": " + e.getMessage());
            }
        }
        if (checked.isEmpty()) {
            throw new BadRequestException("paste at least one rate");
        }
        rates.set(new RateImportInput(checked));
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the rate form: the grade must be A, B or C; the percent is required, 0.00 or more with up
 *  to two decimals (below 100000); a from-date is yyyy-mm-dd, and blank means from the beginning of time; a to-date is yyyy-mm-dd, not before the from-date, and blank means
 *  no end. */
public class ValidateRate {
    private static final Set<String> GRADES = Set.of("A", "B", "C");
    private static final Pattern PCT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?|\\.\\d{1,2}");

    public void validate(@RequestBody RateRequest request, Out<RateInput> rate) throws BadRequestException {
        rate.set(check(request));
    }

    /** Check a rate form by these rules: the rate it sets. */
    static RateInput check(RateRequest request) throws BadRequestException {
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        String pct = request == null || request.pct() == null ? "" : request.pct().trim();
        String from = request == null || request.from() == null ? "" : request.from().trim();
        String to = request == null || request.to() == null ? "" : request.to().trim();
        if (!GRADES.contains(grade)) {
            throw new BadRequestException("grade must be A, B or C");
        }
        if (pct.isEmpty()) {
            throw new BadRequestException("rate is required");
        }
        if (!PCT.matcher(pct).matches()) {
            throw new BadRequestException("rate must be a percent of 0.00 or more with up to two decimals");
        }
        LocalDate on = null;
        if (!from.isEmpty()) {
            try {
                on = LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new BadRequestException("from-date must be yyyy-mm-dd");
            }
        }
        LocalDate until = null;
        if (!to.isEmpty()) {
            try {
                until = LocalDate.parse(to);
            } catch (DateTimeParseException e) {
                throw new BadRequestException("to-date must be yyyy-mm-dd");
            }
        }
        if (until != null && on != null && until.isBefore(on)) {
            throw new BadRequestException("to-date must not be before the from-date");
        }
        return new RateInput(grade, new BigDecimal(pct).setScale(2), on, until);
    }
}
