package net.officefloor.hq.app.history;

import java.sql.Date;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Supplier;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.server.http.HttpHeader;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** A signed-in user's screen showing a sheet as of a date (the X-As-Of header, yyyy-mm-dd): the sheet as it stood
 *  at the end of that day. Every change kept in row_change (see {@link RowCapture}) made while the sheet's today
 *  was on or before the date counts, in the order made, every later one does not (the sheet itself always
 *  exists); the date stands in for the sheet's today. A read replays those changes into the asof schema's tables,
 *  runs the usual read against them, and removes them again, all in one transaction, so no other read sees them.
 *  While the date is set, every change is refused. */
@Component
public class AsOfView {

    public static final String HEADER = "X-As-Of";

    private final JdbcTemplate jdbc;
    private final RowCaptureInstaller installer;
    private final TransactionTemplate transaction;

    public AsOfView(JdbcTemplate jdbc, RowCaptureInstaller installer, PlatformTransactionManager transactions) {
        this.jdbc = jdbc;
        this.installer = installer;
        this.transaction = new TransactionTemplate(transactions);
    }

    /** The as-of date the request's screen shows; null when it shows the sheet as it is now. */
    public static LocalDate of(ServerHttpConnection connection) throws BadRequestException {
        String raw = "";
        for (HttpHeader header : connection.getRequest().getHeaders()) {
            if (HEADER.equalsIgnoreCase(header.getName())) {
                raw = header.getValue() == null ? "" : header.getValue().trim();
                break;
            }
        }
        if (raw.isEmpty()) return null;
        try {
            return LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new BadRequestException("as-of date must be yyyy-mm-dd");
        }
    }

    /** Refuse any change made from a screen showing the sheet as of a date (400, nothing written). */
    public static void refuse(ServerHttpConnection connection) throws BadRequestException {
import { isOpen, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, usePeople } from '../people/usePeople';
import { useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { hundredths, money, rateFor, useRates } from './useRates';

/** A candidate rate's percent: 0.00 or more with up to two decimals (below 100000), as the rate form takes it. */
const PCT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;

/** What a candidate rate would change: how many open (OPEN or PENDING) claims of people on the grade (the grade
 *  they had on the claim's date) would show a different due now were that rate the grade's on every date, and
 *  the sum of new due minus current due. A claim a statement binds keeps its figure; a settled one is not open.
 *  Returns a function computing it from the sheet as loaded; it throws on a bad percent. Saves nothing. */
export function useRatePreview(sheetId: string): (grade: string, pct: string) => { count: number; diff: string } {
  const people = usePeople(sheetId).data;
  const claims = useClaims(sheetId).data;
  const rates = useRates(sheetId).data;
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId).data?.today;
  return (grade, pct) => {
    const candidate = pct.trim();
    if (candidate === '') throw new Error('rate is required');
    if (!PCT.test(candidate)) throw new Error('rate must be a percent of 0.00 or more with up to two decimals');
    const asPct = money(hundredths(candidate.startsWith('.') ? `0${candidate}` : candidate));
    let count = 0;
    let diff = 0n;
    for (const c of claims ?? []) {
      if (!isOpen(c)) continue;
      const p = (people ?? []).find((x) => x.id === c.personId);
      const g = gradeOn(p, c.date);
      if (g !== grade) continue;
      const now = claimDueNow(c, claims, rateFor(rates, g, c.date), settings, today, g);
      const next = claimDueNow(c, claims, asPct, settings, today, g);
      if (now === next) continue;
      count++;
      diff += (next === 'n/a' ? 0n : hundredths(next)) - (now === 'n/a' ? 0n : hundredths(now));
    }
    return { count, diff: money(diff) };
  };
}

